Here is the root cause:
The bug is an infinite loop in `shmem_undo_range` when truncating a large swap entry at a middle index. `shmem_free_swap()` fails because the entry's base index is smaller than the given `index` (due to alignment). The fallback code only checks if the entry crosses the `end` boundary; when it does not, it retries with the same `index`. This causes `find_get_entries()` to repeatedly return the same large entry, never making progress. The fix rounds down the index to the entry's base and also checks the start boundary to avoid retrying incorrectly.

Here is the patch:
  */
 static void shmem_undo_range(struct inode *inode, loff_t lstart, uoff_t lend,
 								 bool unfalloc)
 {
 	struct address_space *mapping = inode->i_mapping;
 	struct shmem_inode_info *info = SHMEM_I(inode);
 	pgoff_t start = (lstart + PAGE_SIZE - 1) >> PAGE_SHIFT;
 	pgoff_t end = (lend + 1) >> PAGE_SHIFT;
 	struct folio_batch fbatch;
 	pgoff_t indices[PAGEVEC_SIZE];
 	struct folio *folio;
 	bool same_folio;
 	long nr_swaps_freed = 0;
 	pgoff_t index;
 	int i;

 	if (lend == -1)
 		end = -1;	/* unsigned, so actually very big */

 	if (info->fallocend > start && info->fallocend <= end && !unfalloc)
 		info->fallocend = start;

 	folio_batch_init(&fbatch);
 	index = start;
 	while (index < end && find_lock_entries(mapping, &index, end - 1,
 			&fbatch, indices)) {
 		for (i = 0; i < folio_batch_count(&fbatch); i++) {
 			folio = fbatch.folios[i];

 			if (xa_is_value(folio)) {
 				if (unfalloc)
 					continue;
 				nr_swaps_freed += shmem_free_swap(mapping, indices[i],
 								  end - 1, folio);
 				continue;
 			}

 			if (!unfalloc || !folio_test_uptodate(folio))
 				truncate_inode_folio(mapping, folio);
 			folio_unlock(folio);
 		}
 		folio_batch_remove_exceptionals(&fbatch);
 		folio_batch_release(&fbatch);
 		cond_resched();
 	}

 	/*
 	 * When undoing a failed fallocate, we want none of the partial folio
 	 * zeroing and splitting below, but shall want to truncate the whole
 	 * folio when !uptodate indicates that it was added by this fallocate,
 	 * even when [lstart, lend] covers only a part of the folio.
 	 */
 	if (unfalloc)
 		goto whole_folios;

 	same_folio = (lstart >> PAGE_SHIFT) == (lend >> PAGE_SHIFT);
 	folio = shmem_get_partial_folio(inode, lstart >> PAGE_SHIFT);
 	if (folio) {
 		same_folio = lend < folio_next_pos(folio);
 		folio_mark_dirty(folio);
 		if (!truncate_inode_partial_folio(folio, lstart, lend)) {
 			start = folio_next_index(folio);
 			if (same_folio)
 				end = folio->index;
 		}
 		folio_unlock(folio);
 		folio_put(folio);
 		folio = NULL;
 	}

 	if (!same_folio)
 		folio = shmem_get_partial_folio(inode, lend >> PAGE_SHIFT);
 	if (folio) {
 		folio_mark_dirty(folio);
 		if (!truncate_inode_partial_folio(folio, lstart, lend))
 			end = folio->index;
 		folio_unlock(folio);
 		folio_put(folio);
 	}

 whole_folios:

 	index = start;
 	while (index < end) {
 		cond_resched();

 		if (!find_get_entries(mapping, &index, end - 1, &fbatch,
 				indices)) {
 			/* If all gone or hole-punch or unfalloc, we're done */
 			if (index == start || end != -1)
 				break;
 			/* But if truncating, restart to make sure all gone */
 			index = start;
 			continue;
 		}
 		for (i = 0; i < folio_batch_count(&fbatch); i++) {
 			folio = fbatch.folios[i];

 			if (xa_is_value(folio)) {
 				int order;
 				long swaps_freed;

 				if (unfalloc)
 					continue;
 				swaps_freed = shmem_free_swap(mapping, indices[i],
 							      end - 1, folio);
 				if (!swaps_freed) {
-					/*
-					 * If found a large swap entry cross the end border,
-					 * skip it as the truncate_inode_partial_folio above
-					 * should have at least zerod its content once.
-					 */
+					pgoff_t base = indices[i];
+
 					order = shmem_confirm_swap(mapping, indices[i],
 								   radix_to_swp_entry(folio));
-					if (order > 0 && indices[i] + (1 << order) > end)
-						continue;
-					/* Swap was replaced by page: retry */
-					index = indices[i];
+					/*
+					 * If found a large swap entry cross the end or start
+					 * border, skip it as the truncate_inode_partial_folio
+					 * above should have at least zerod its content once.
+					 */
+					if (order > 0) {
+						base = round_down(base, 1 << order);
+						if (base < start || base + (1 << order) > end)
+							continue;
+					}
+					/* Swap was replaced by page or extended, retry */
+					index = base;
 					break;
 				}
 				nr_swaps_freed += swaps_freed;
 				continue;
 			}

 			folio_lock(folio);

 			if (!unfalloc || !folio_test_uptodate(folio)) {
 				if (folio_mapping(folio) != mapping) {
 					/* Page was replaced by swap: retry */
 					folio_unlock(folio);
 					index = indices[i];
 					break;
 				}
 				VM_BUG_ON_FOLIO(folio_test_writeback(folio),
 						folio);

 				if (!folio_test_large(folio)) {
 					truncate_inode_folio(mapping, folio);
 				} else if (truncate_inode_partial_folio(folio, lstart, lend)) {
 					/*
 					 * If we split a page, reset the loop so
 					 * that we pick up the new sub pages.
 					 * Otherwise the THP was entirely
 					 * dropped or the target range was
 					 * zeroed, so just continue the loop as
 					 * is.
 					 */
 					if (!folio_test_large(folio)) {
 						folio_unlock(folio);
 						index = start;
 						break;
 					}
 				}
 			}
 			folio_unlock(folio);
 		}
 		folio_batch_remove_exceptionals(&fbatch);
 		folio_batch_release(&fbatch);
 	}

 	shmem_recalc_inode(inode, 0, -nr_swaps_freed);
 }



